// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 count) public {
        vm.assume(count >= 2 && count <= 10);
        vm.deal(address(this), (10 ether) * count);
        vm.warp(100);
        vm.roll(1);
        for (uint256 i = 0; i < count; i++) {
            (bool ok,) = address(c).call{value: 10 ether}("");
            if (!ok) {
                assertTrue(!ok);
                return;
            }
            uint256 ts = block.timestamp;
            uint256 pbt = c.pastBlockTime();
            assertTrue(pbt > ts);
        }
    }
}
